css_before:
/* Static fallen leaves live only at the document floor, below footer text. */
body > footer{border-bottom:44px solid #fafbf7}
body > .platform-leaf-layer::after{content:"";position:absolute;bottom:0;left:0;width:100%;height:44px;pointer-events:none;background:url("platform-assets/leaf-floor.svg") center bottom/960px 44px repeat-x;image-rendering:pixelated;opacity:.8}
@media(max-width:760px){
 body > footer{border-bottom-width:36px}
 body > .platform-leaf-layer::after{height:36px;background-size:720px 36px}
}

css_after:
/* Fixed floor reservation prevents layout shifts; leaf clusters accumulate once. */
body > footer{border-bottom:112px solid #fafbf7}
body > .platform-leaf-layer::after{content:"";position:absolute;bottom:0;left:0;width:100%;height:112px;pointer-events:none;background:url("platform-assets/leaf-piles-base.svg") center bottom/960px 112px repeat-x;image-rendering:pixelated;opacity:.8}
body > .platform-leaf-layer > .platform-pile{position:absolute;bottom:0;left:0;width:100%;height:112px;pointer-events:none;background-position:center bottom;background-size:960px 112px;background-repeat:repeat-x;image-rendering:pixelated;opacity:0;animation:platform-pile-arrive 6s steps(6,end) forwards}
body > .platform-leaf-layer > .platform-pile:nth-of-type(7){background-image:url("platform-assets/leaf-pile-growth-1.svg");animation-delay:20s}
body > .platform-leaf-layer > .platform-pile:nth-of-type(8){background-image:url("platform-assets/leaf-pile-growth-2.svg");animation-delay:45s}
body > .platform-leaf-layer > .platform-pile:nth-of-type(9){background-image:url("platform-assets/leaf-pile-growth-3.svg");animation-delay:75s}
body > .platform-leaf-layer > .platform-pile:nth-of-type(10){background-image:url("platform-assets/leaf-pile-growth-4.svg");animation-delay:110s}
body > .platform-leaf-layer > .platform-pile:nth-of-type(11){background-image:url("platform-assets/leaf-pile-growth-5.svg");animation-delay:155s}
body > .platform-leaf-layer > .platform-pile:nth-of-type(12){background-image:url("platform-assets/leaf-pile-growth-6.svg");animation-delay:210s}
@keyframes platform-pile-arrive{from{opacity:0}to{opacity:.8}}
@media(max-width:760px){
 body > footer{border-bottom-width:84px}
 body > .platform-leaf-layer::after,body > .platform-leaf-layer > .platform-pile{height:84px;background-size:720px 84px}
}
@media(prefers-reduced-motion:reduce){
 body > .platform-leaf-layer > .platform-pile{animation:none;opacity:.5}
}
